const raw = $input.first().json.choices[0].message.content;
const cleaned = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  throw new Error('GPT JSON parse failed. Raw: ' + cleaned.substring(0, 300));
}

const roles = ['hook', 'problem', 'tip_1', 'tip_2', 'micro_story', 'cta'];
let slides = [];

function extractSlide(obj, index) {
  // Standard: {headline, subtext}
  if (obj.headline && obj.subtext) {
    return { index: obj.index || index, role: obj.role || roles[index-1], headline: obj.headline, subtext: obj.subtext };
  }
  // Role-prefixed: {hook_headline, hook_subtext} or {tip_1_headline, tip_1_subtext}
  const hKey = Object.keys(obj).find(k => k.endsWith('_headline'));
  const sKey = Object.keys(obj).find(k => k.endsWith('_subtext'));
  if (hKey && sKey) {
    return { index: index, role: hKey.replace('_headline',''), headline: obj[hKey], subtext: obj[sKey] };
  }
  return null;
}

if (Array.isArray(parsed.slides)) {
  slides = parsed.slides.map((s, i) => extractSlide(s, i + 1)).filter(Boolean);
} else if (parsed.slides && typeof parsed.slides === 'object') {
  slides = Object.values(parsed.slides).map((s, i) => extractSlide(s, i + 1)).filter(Boolean);
} else {
  // Top-level flat: {slide_1_hook_headline, slide_2_problem_headline, ...}
  for (let i = 1; i <= 6; i++) {
    const hKey = Object.keys(parsed).find(k => k.startsWith('slide_' + i + '_') && k.endsWith('_headline'));
    const sKey = Object.keys(parsed).find(k => k.startsWith('slide_' + i + '_') && k.endsWith('_subtext'));
    if (hKey && sKey) {
      const role = hKey.replace('slide_' + i + '_', '').replace('_headline', '');
      slides.push({ index: i, role, headline: parsed[hKey], subtext: parsed[sKey] });
    }
  }
}

if (!slides.length || !slides[0].headline) {
  throw new Error('No slides with headline extracted. Keys: ' + Object.keys(parsed).join(', ') + ' | First slide keys: ' + (parsed.slides && Array.isArray(parsed.slides) ? Object.keys(parsed.slides[0]).join(', ') : 'n/a'));
}

return slides.map(slide => ({
  json: {
    slide_index:   slide.index,
    slide_role:    slide.role,
    headline:      slide.headline,
    subtext:       slide.subtext,
    caption:       parsed.caption,
    first_comment: parsed.first_comment,
    image_keyword: parsed.image_keyword
  }
}));

const items = $input.all();
const image_urls = items.map(i => i.json.secure_url);
return [{
  json: {
    image_urls:    image_urls,
    caption:       $('Parse GPT Response').first().json.caption,
    first_comment: $('Parse GPT Response').first().json.first_comment
  }
}];

const urls = $input.first().json.image_urls;
const caption = $input.first().json.caption;
const first_comment = $input.first().json.first_comment;

return urls.map(url => ({
  json: {
    image_url: url,
    caption: caption,
    first_comment: first_comment
  }
}));

const items = $input.all();

const children = items.map(i => i.json.id);

return [{
  json: {
    children: children,
    caption: $('Collect Slide Data').first().json.caption,
    first_comment: $('Collect Slide Data').first().json.first_comment
  }
}];

const result = $input.first().json.results[0];
const props = result.properties;

const getString = (p) => p?.rich_text?.[0]?.plain_text || p?.title?.[0]?.plain_text || '';
const getSelect = (p) => p?.select?.name || '';
const getNumber = (p) => p?.number || 0;

return [{
  json: {
    body: {
      action: 'publish',
      topic: getString(props.Topic),
      summary: getString(props.Summary),
      tone: getSelect(props.Tone),
      image_keyword: getString(props['Image Keyword']),
      notion_page_id: result.id,
      metadata: {
        category: getSelect(props.Category),
        priority: getSelect(props.Priority),
        platform: 'instagram',
        post_type: getSelect(props['Post Type']) || 'carousel',
        trend_score: getNumber(props['Trend Score']),
        source: getSelect(props.Source),
        campaign_tag: getSelect(props['Campaign Tag']),
        scheduled_time: '',
        skip_reason: ''
      }
    }
  }
}];

